import { readFile, mkdir, mkdtemp, writeFile, readdir } from 'node:fs/promises';
import { createRequire } from 'node:module';
import { pathToFileURL } from 'node:url';
import { join } from 'node:path';
import { randomUUID } from 'node:crypto';
const base = '/home/genie/.local/share/mikro-engine-split/experiments-g8';
const resources = JSON.parse(await readFile(process.argv[2], 'utf8'));
const binding = resources.native.find(row => row.id === 'g8-native-smoke');
const profile = JSON.parse(await readFile(binding.profilePath, 'utf8'));
const proofRoot = await mkdtemp(join(base, 'native-context-guard-proof-'));
const cwd = binding.callerAgentsDir.split('/.g8-runtime/')[0];
const callerRoot = join(cwd, '.g8-runtime/genie/mikro/runs');
await mkdir(callerRoot, { recursive: true, mode: 0o700 });
const context = join(callerRoot, `unscored-context-guard-${randomUUID()}.json`);
await writeFile(context, '[]\n', { flag: 'wx', mode: 0o600 });
const outsideContext = join(proofRoot, 'outside-context.json'); await writeFile(outsideContext, '[]\n', { flag: 'wx', mode: 0o600 });
const receiptDir = join(profile.receiptRoot, `unscored-context-guard-${randomUUID()}`);
const require = createRequire(join(profile.artifactRoot, 'package.json'));
const { Client } = await import(pathToFileURL(require.resolve('@modelcontextprotocol/sdk/client/index.js')).href);
const { StdioClientTransport } = await import(pathToFileURL(require.resolve('@modelcontextprotocol/sdk/client/stdio.js')).href);
const transport = new StdioClientTransport({ command: '/home/genie/.hermes/node/bin/node', args: ['/home/genie/orca/workspaces/genie/mikro-engine-split/scripts/mikro/engine-experiment-runtime.mjs', '--profile', binding.profilePath, 'mcp'], cwd, env: { PATH: profile.runtimePath, HOME: profile.homeRoot, TMPDIR: '/tmp', MIKRO_EXPERIMENT_RECEIPT_DIR: receiptDir }, stderr: 'pipe' });
const client = new Client({ name: 'native-facts-security-proof', version: '1' }, { capabilities: {} });
let stderr = ''; transport.stderr?.on('data', bytes => { stderr += bytes.toString(); });
const proof = { schemaVersion: 1, kind: 'actual-MCP-facts-guard-precedence-no-inference', profilePath: binding.profilePath, proofRoot, contextRoots: profile.contextRoots, context, outsideContext, receiptDir, modelCalls: 0, realNativeWorkflowLaunched: false };
try {
  await client.connect(transport);
  const tools = await client.listTools();
  const tool = tools.tools.find(item => item.name.includes('wish') && item.name.includes('context'));
  if (!tool) throw new Error(`actual wish-context tool missing: ${tools.tools.map(item => item.name).join(',')}`);
  const session_id = randomUUID();
  proof.allowedContextResult = await client.callTool({ name: tool.name, arguments: { prompt: 'Unscored context-path guard proof; never dispatch a backend', context, session_id } });
  proof.outsideContextResult = await client.callTool({ name: tool.name, arguments: { prompt: 'Unscored context-path guard proof; never dispatch a backend', context: outsideContext, session_id } });
  const text = result => result.content.filter(item => item.type === 'text').map(item => item.text).join('\n');
  if (text(proof.allowedContextResult) !== 'unknown or busy session') throw new Error(`declared actual facts root rejected before session guard: ${text(proof.allowedContextResult)}`);
  if (text(proof.outsideContextResult) !== 'context is not within frozen external facts roots') throw new Error('outside context guard failed');
  proof.receiptFiles = await readdir(receiptDir);
  if (proof.receiptFiles.some(name => name.endsWith('.started.json') || name.endsWith('.result.json'))) throw new Error('unexpected backend lifecycle dispatch');
  proof.success = true;
} catch (error) { proof.success = false; proof.failure = { name: error.name, message: error.message, code: error.code ?? null }; }
finally {
  await client.close(); await transport.close();
  proof.stderr = stderr;
  await writeFile(join(proofRoot, 'proof.json'), `${JSON.stringify(proof, null, 2)}\n`, { flag: 'wx', mode: 0o600 });
  console.log(JSON.stringify({ proofPath: join(proofRoot, 'proof.json'), success: proof.success, modelCalls: 0, failure: proof.failure ?? null }));
}
if (!proof.success) process.exitCode = 2;
